// Representation only: constants plus immutable interned symbolic coefficient
// vectors. All nontrivial operations use the existing qualified bounded algebra.
#[derive(Clone,Copy,Default,Debug,PartialEq,Eq,Hash)]struct CompactValue{c:u64,sym:u32}
impl CompactValue{fn known(c:u64)->Self{Self{c,sym:0}}}
struct CompactAlgebra{alg:Algebra,forms:Vec<Vec<(u32,u64)>>,intern:HashMap<Vec<(u32,u64)>,u32>}
impl CompactAlgebra{
 fn new()->Self{Self{alg:Algebra::new(),forms:vec![vec![]],intern:HashMap::new()}}
 fn encode(&mut self,p:Poly)->CompactValue{if p.terms.is_empty(){return CompactValue::known(p.c);}let sym=if let Some(&id)=self.intern.get(&p.terms){id}else{let id=self.forms.len().try_into().unwrap();self.forms.push(p.terms.clone());self.intern.insert(p.terms,id);id};CompactValue{c:p.c,sym}}
 fn decode(&self,v:CompactValue)->Poly{Poly{c:v.c,terms:self.forms[v.sym as usize].clone()}}
 fn tv(&self,v:CompactValue)->TV{let unknown=self.forms[v.sym as usize].iter().fold(0u64,|mask,(_,c)|mask|c);TV{z:!v.c&!unknown,o:v.c&!unknown}}
 fn bound_value(&mut self,v:CompactValue)->CompactValue{if self.forms[v.sym as usize].len()+usize::from(v.c!=0)<=8{return v;}let p=self.decode(v);let p=self.alg.bound(p);self.encode(p)}
 fn xor(&mut self,a:CompactValue,b:CompactValue)->CompactValue{if a.sym==b.sym{return CompactValue::known(a.c^b.c);}if a.sym==0{return self.bound_value(CompactValue{c:a.c^b.c,sym:b.sym});}if b.sym==0{return self.bound_value(CompactValue{c:a.c^b.c,sym:a.sym});}let(a,b)=(self.decode(a),self.decode(b));let p=self.alg.xor(&a,&b);self.encode(p)}
 fn not(&mut self,a:CompactValue)->CompactValue{self.bound_value(CompactValue{c:!a.c,sym:a.sym})}
 fn and(&mut self,a:CompactValue,b:CompactValue)->CompactValue{if a==b{return a;}if a.sym==0&&b.sym==0{return CompactValue::known(a.c&b.c);}if a.sym==0{if a.c==0{return CompactValue::known(0);}if a.c==u64::MAX{return b;}}if b.sym==0{if b.c==0{return CompactValue::known(0);}if b.c==u64::MAX{return a;}}let(a,b)=(self.decode(a),self.decode(b));let p=self.alg.and(&a,&b);self.encode(p)}
 fn ite(&mut self,g:CompactValue,a:CompactValue,b:CompactValue)->CompactValue{if a==b{return a;}let x=self.xor(a,b);let y=self.and(g,x);self.xor(b,y)}
}
pub(super)fn eval(p:&Program,initial_q:&[u64],initial_bits:&[u64])->Vec<TV>{let mut alg=CompactAlgebra::new();let mut q:Vec<_>=initial_q.iter().copied().map(CompactValue::known).collect();let mut c=vec![CompactValue::default();p.versions];for(i,&v)in initial_bits.iter().enumerate(){c[i]=CompactValue::known(v);}let mut random=HashMap::new();
 for(i,n)in p.nodes.iter().enumerate(){if alg.alg.monos.len()>16_000_000||alg.forms.len()>1_000_000{eprintln!("COMPACT_ANF_BUDGET_EXHAUSTED at={i} sound_TV_continuation");return finish(p,i,q.iter().map(|&v|alg.tv(v)).collect(),c.iter().map(|&v|alg.tv(v)).collect());}let mut g=CompactValue::known(u64::MAX);for &v in &p.guards[n.g as usize]{g=alg.and(g,c[v as usize]);}let t=n.t as usize;match n.k{QX=>q[t]=alg.xor(q[t],g),QCX=>{let x=alg.and(g,q[n.a as usize]);q[t]=alg.xor(q[t],x);},QCCX=>{let a=alg.and(g,q[n.a as usize]);let x=alg.and(a,q[n.b as usize]);q[t]=alg.xor(q[t],x);},QSWAP=>{let a=n.a as usize;let x=alg.xor(q[a],q[t]);let x=alg.and(g,x);q[a]=alg.xor(q[a],x);q[t]=alg.xor(q[t],x);},QZERO=>{let ng=alg.not(g);q[t]=alg.and(q[t],ng);},CINV=>c[t]=alg.xor(c[n.a as usize],g),CZERO=>{let ng=alg.not(g);c[t]=alg.and(c[n.a as usize],ng);},CONE=>c[t]=alg.ite(g,CompactValue::known(u64::MAX),c[n.a as usize]),CRNG=>{let id=*random.entry(n.r).or_insert_with(||alg.alg.atom(0));let fresh=alg.encode(Poly{c:0,terms:vec![(id,u64::MAX)]});c[t]=alg.ite(g,fresh,c[n.a as usize]);},_=>unreachable!()}}
 eprintln!("COMPACT_ANF_COMPLETE monomials={} product_cache={} opaque_cache={} coefficient_forms={}",alg.alg.monos.len(),alg.alg.products.len(),alg.alg.opaque.len(),alg.forms.len());q.iter().map(|&v|alg.tv(v)).collect()
}
#[cfg(test)]mod compact_value_tests{use super::*;
 #[test]fn constant_hot_path_and_repeated_symbolic_identity_do_not_allocate_forms(){let mut a=CompactAlgebra::new();let mut v=CompactValue::known(0xa55a_dd33_ff00_1188);for i in 0..1000{v=a.xor(v,CompactValue::known(i));v=a.and(v,CompactValue::known(0xff00_ff00_ff00_ff00));v=a.not(v);}assert_eq!(a.forms.len(),1);assert_eq!(a.alg.monos.len(),1);let p=a.alg.variable(0xa55a_dd33_ff00_1188);let v=a.encode(p);assert_eq!(a.xor(v,v),CompactValue::known(0));assert_eq!(a.and(v,CompactValue::known(u64::MAX)),v);}
 #[test]fn eight_symbolic_terms_plus_nonzero_constant_still_obeys_original_total_term_bound(){let mut a=CompactAlgebra::new();let terms:Vec<_>=(0..8).map(|_|(a.alg.atom(u64::MAX),u64::MAX)).collect();let p=Poly{c:0,terms};let v=a.encode(p);let out=a.xor(v,CompactValue::known(1));assert!(a.decode(out).effective_terms()<=8);assert_eq!(a.alg.value(&a.decode(out)),1);assert!(!a.alg.opaque.is_empty());}
 #[test]fn interned_values_preserve_exact_concrete_and_sound_known_bits_under_random_boolean_operations(){let mut a=CompactAlgebra::new();let mut values=vec![];for bit in 0..6{let mut truth=0;for lane in 0..64{truth|=(((lane>>bit)&1)as u64)<<lane;}let p=a.alg.variable(truth);values.push(a.encode(p));}values.push(CompactValue::known(0xa55a_dd33_ff00_1188));let mut seed=0xa8d7135f23649b01u64;for _ in 0..1500{seed=seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);let(x,y,g)=(values[seed as usize%values.len()],values[(seed>>17)as usize%values.len()],values[(seed>>33)as usize%values.len()]);let(xv,yv,gv)=(a.alg.value(&a.decode(x)),a.alg.value(&a.decode(y)),a.alg.value(&a.decode(g)));let(result,expected)=match seed%4{0=>(a.xor(x,y),xv^yv),1=>(a.and(x,y),xv&yv),2=>(a.not(x),!xv),_=>(a.ite(g,x,y),(gv&xv)|(!gv&yv))};let actual=a.alg.value(&a.decode(result));assert_eq!(actual,expected);let tv=a.tv(result);assert_eq!(actual&(tv.z|tv.o),tv.o);assert_eq!(tv.z&tv.o,0);assert!(a.decode(result).effective_terms()<=8);if values.len()<64{values.push(result);}else{values[(seed>>8)as usize%64]=result;}}}
}
